+    static stnode_t *
+    new_reference(dfsyntax_t *dfs _U_, stnode_t *node)
+    {
+        /* convert field to reference */
+        stnode_t *ref = stnode_new(STTYPE_REFERENCE, sttype_field_hfinfo(node), NULL, stnode_location(node));
